// LeetCode 0207 - Course Schedule
#include <stdbool.h>
#include <stdlib.h>
bool canFinish(int numCourses, int** prerequisites, int prerequisitesSize, int* prerequisitesColSize) { int *head = malloc((size_t)numCourses * sizeof(int)), *to = malloc((size_t)prerequisitesSize * sizeof(int)), *next = malloc((size_t)prerequisitesSize * sizeof(int)), *indegree = calloc((size_t)numCourses, sizeof(int)), *queue = malloc((size_t)numCourses * sizeof(int)); for (int i = 0; i < numCourses; ++i) head[i] = -1; for (int i = 0; i < prerequisitesSize; ++i) { int course = prerequisites[i][0], pre = prerequisites[i][1]; to[i] = course; next[i] = head[pre]; head[pre] = i; ++indegree[course]; } int front = 0, back = 0, taken = 0; for (int i = 0; i < numCourses; ++i) if (!indegree[i]) queue[back++] = i; while (front < back) { int course = queue[front++]; ++taken; for (int edge = head[course]; edge != -1; edge = next[edge]) if (--indegree[to[edge]] == 0) queue[back++] = to[edge]; } free(head); free(to); free(next); free(indegree); free(queue); return taken == numCourses; }
